{
  "pipeline": [
    { "$unwind": "$items" },
    {
      "$group": {
        "_id": "$items.name",
        "totalRevenue": {
          "$sum": {
            "$multiply": [
              { "$toDecimal": "$items.price.val" },
              "$items.quantity"
            ]
          }
        },
        "totalUnitsSold": { "$sum": "$items.quantity" }
      }
    },
    { "$sort": { "totalRevenue": -1 } },
    { "$limit": 10 },
    {
      "$project": {
        "_id": 0,
        "product": "$_id",
        "totalRevenue": 1,
        "totalUnitsSold": 1
      }
    }
  ],
  "collection": "sales",
  "chartType": "bar",
  "explanation": "Aggregates sales data to find the top 10 products by total revenue (price multiplied by quantity), showing revenue and units sold for each product."
}

