    { "$unwind": "$items" },
    { "$sort": { "items.price": 1 } },
    { "$limit": 2 },
    { "$project": { "_id": 0, "productName": "$items.name", "price": "$items.price" } }
  ],
  "collection": "sales",
  "chartType": "table",
  "explanation": "Unwinds the items array, sorts all products by their price in ascending order, limits to the two cheapest items, and returns their names and prices."
}

{
  "pipeline": [
    {
      "$match": {
        "items": {
          "$elemMatch": {
            "price.val": "40.01"
          }
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "saleDate": 1,
        "storeLocation": 1,
        "customer": 1,
        "couponUsed": 1,
        "purchaseMethod": 1,
        "items": 1
      }
    }
  ],
  "collection": "sales",
  "chartType": "table",
  "explanation": "Filters sales documents to those where at least one item has a price of 40.01, then returns the relevant transaction fields for display."
}
